function maxMeetings(intervals) {
  if (intervals.length === 0) return 0;
  const sorted = [...intervals].sort(function byFinish(left, right) {
    return left[1] - right[1] || left[0] - right[0];
  });
  let count = 0;
  let end = -Infinity;
  for (const interval of sorted) {
    if (interval[0] >= end) {
      count += 1;
      end = interval[1];
    }
  }
  return count;
}
